JS='''
document.querySelectorAll('[data-tabs]').forEach(root=>{const buttons=[...root.querySelectorAll('[role=tab]')];buttons.forEach(b=>b.addEventListener('click',()=>{buttons.forEach(other=>{const selected=other===b;other.setAttribute('aria-selected',String(selected));document.getElementById(other.getAttribute('aria-controls')).hidden=!selected;});}));});
document.querySelectorAll('[data-filter]').forEach(input=>input.addEventListener('input',()=>{const query=input.value.toLocaleLowerCase('fr');const selector=input.dataset.filter;let shown=0;document.querySelectorAll(selector).forEach(el=>{const visible=el.textContent.toLocaleLowerCase('fr').includes(query);el.hidden=!visible;if(visible)shown++;});const counter=document.getElementById(input.dataset.counter);if(counter)counter.textContent=shown+' élément(s) affiché(s)';}));
document.querySelectorAll('[data-group]').forEach(sel=>sel.addEventListener('change',()=>{document.querySelectorAll('.modulelist .modlink').forEach(el=>el.hidden=sel.value!==''&&el.dataset.group!==sel.value);}));
document.querySelectorAll('[data-navigation]').forEach(sel=>sel.addEventListener('change',()=>{if(sel.value)location.href=sel.value;}));
document.querySelectorAll('[data-print]').forEach(b=>b.addEventListener('click',()=>window.print()));
'''

def href(key):
    return ('index.html' if key=='overview' else key+'.html' if key in {'accounts','roadmap','sources'} else 'modules/'+key+'.html')

def badge(text,kind=''):
    return f'<span class="badge {E(kind)}">{E(text)}</span>'

def ul(values):
    return '<ul>'+''.join('<li>'+E(v)+'</li>' for v in values)+'</ul>'

def page(key,title,body,module=False):
    prefix='../' if module else ''
    nav=''.join(f'<a class="summarylink {"current" if key==k else ""}" href="{prefix}{href(k)}">{label}</a>' for k,label in [('overview','Vue globale'),('accounts','Comptes et environnements'),('roadmap','Plan d’action'),('sources','Sources et méthode')])
    for group in GROUPS:
        nav+='<p class="navgroup">'+E(group)+'</p>'
        nav+=''.join(f'<a class="{"current" if key==m["id"] else ""}" href="{prefix}{href(m["id"])}">{E(m["title"])}</a>' for m in MODULES if m['group']==group)
    options=''.join(f'<option value="{prefix}{href(m["id"])}" {"selected" if key==m["id"] else ""}>{E(m["title"])}</option>' for m in MODULES)
    document=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Structura — {E(title)}</title><style>{CSS}</style></head><body>
    <header class="topbar"><a class="brand" href="{prefix}index.html">STRUCTURA <span class="muted">/ Atlas</span></a><nav class="topnav" aria-label="Navigation globale"><a href="{prefix}index.html">Vue globale</a><a href="{prefix}accounts.html">Comptes</a><a href="{prefix}roadmap.html">Plan d’action</a><a href="{prefix}sources.html">Sources</a></nav><span class="stamp">Photographie du 13 octobre 2026</span></header>
    <div class="layout"><aside class="sidebar" aria-label="Modules">{nav}<p class="scope">Lecture de la base et du code.<br>Aucun changement de comptes, de droits ou de données métier.</p></aside><main id="main"><div class="page"><select class="mobileNav" data-navigation aria-label="Choisir un module"><option value="">Accéder à un module…</option>{options}</select>{body}<footer>État observé au 13/10/2026 · Branche {E(DATA['source_branch'])} · Base principale et environnements isolés distingués.<br>Code présent ≠ recette complète ≠ déploiement externe. Toutes les pages fonctionnent sans connexion réseau.</footer></div></main></div><script>{JS}</script></body></html>'''
    path=OUT/('modules' if module else '')/('index.html' if key=='overview' else key+'.html')
    path.parent.mkdir(parents=True,exist_ok=True)
    path.write_text(document,encoding='utf-8')

def metrics(values):
    return '<div class="metrics">'+''.join(f'<div class="metric"><div class="value">{E(v)}</div><div class="label">{E(label)}</div></div>' for v,label in values)+'</div>'

def modules_grid():
    return '<div class="modulelist">'+''.join(f'<a class="modlink" data-group="{E(m["group"])}" href="modules/{m["id"]}.html"><small>{E(m["group"])}</small><h3>{E(m["title"])}</h3>{badge(m["state"])}<p>{E(m["goal"])}</p></a>' for m in MODULES)+'</div>'

def overview():
    body='<div class="eyebrow">Carte fonctionnelle · état des lieux</div><h1>Comprendre Structura<br>et savoir où reprendre.</h1><p class="lead">Une application de produits structurés : préparation commerciale, contrat Product, pricing, RFQ, booking, cycle de vie, risque et documents. Les études AMC et les simulations ont leurs propres périmètres.</p>'
    body+=metrics([('10','Comptes de la base principale'),('3','Organisations locales'),(str(len(MODULES)),'Fiches de module'),('53','Bases secondaires recensées')])
    body+='<div class="notice"><strong>Le compte de travail principal est test.</strong> Il porte les 38 Deals, 72 Product et 42 RFQ actuels. admin gère les référentiels et possède les 6 campagnes de simulation ; bnp.pricing est le répondant de la BNP locale. Les noms BNP des simulations ne désignent pas une connexion à une banque réelle.</div>'
    body+='<div class="notice warn"><strong>Livré et chargé sont deux états différents.</strong> Le code des lots RFQ 7–8 est présent, mais leurs tables d’accord et d’unicité de booking sont absentes de la base principale. La remise locale d’une RFQ existe ; aucun prix bancaire n’y est publié et aucun canal distant n’est configuré.</div>'
    body+='<h2>Le parcours principal</h2><p class="muted">Chaque étape apporte ses propres faits. Une RFQ envoyée n’est pas un ordre ; un Product conservé n’est pas un Deal ; une constatation n’est pas un paiement.</p><div class="flow">'
    steps=[('clients','Client / besoin','Facultatif : société, mandat, opportunité.'),('products','Product + Pricer','Termes et calendriers, marché séparé.'),('rfq','RFQ','Manuel ou destinataires autorisés.'),('rfq-bank','Banque','Calcul privé, validation, publication.'),('booking','Accord + Deal','Accord consigné, contrôles, booking unique.'),('lifecycle','Life Cycle','Fixings, résolutions, flux et paiements.'),('mtm','MtM / risque / notes','Valorisations et décisions en vie.')]
    for index,(key,title,text) in enumerate(steps):
        if index:body+='<span class="arrow" aria-hidden="true">→</span>'
        body+=f'<a class="step" href="modules/{key}.html"><span class="num">ÉTAPE {index+1}</span><strong>{E(title)}</strong>{E(text)}</a>'
    body+='</div><h2>Qui échange quoi ?</h2><div class="diagramline"><div class="end"><h3><a href="modules/rfq.html">Installation demandeuse</a></h3><p>Organisation → desk Sales → RFQ et Product. Les fournisseurs autorisés viennent de la relation bilatérale.</p><p>Reçoit le prix publié, compare, choisit, consigne l’accord externe et booke localement.</p></div><div class="connector" aria-label="Échanges dans les deux sens">⇄</div><div class="end"><h3><a href="modules/rfq-bank.html">Installation bancaire</a></h3><p>Desk Pricing → même contrat → Product privé bancaire. Marché, modèle et calcul restent privés.</p><p>Valide le prix commercial selon sa politique puis publie. La V1 ne pilote pas un système de pricing BNP externe.</p></div></div><p class="note">Transport natif : demandes, lectures, publications, retraits et clôtures. Acceptation/confirmation natives et rapprochement des books : compléments. La V1 consigne un accord reçu hors réseau.</p>'
    body+='<div class="sectiongrid"><section class="panel"><h3>Structurer et rechercher</h3><p>Le catalogue/PayScript nourrit le Pricer. L’Optimizer explore des candidats et conserve des recherches ; un choix doit encore rejoindre un parcours Product / RFQ / exécution explicite.</p><div class="related"><a href="modules/scripts.html">PayScript</a><a href="modules/pricing.html">Pricer</a><a href="modules/optimizer.html">Optimizer</a></div></section><section class="panel"><h3>Étudier et recetter</h3><p>Studies/FIFO analyse des AMC, ordres, NAV et facteurs. Le simulateur fait utiliser les modules natifs à des acteurs fictifs, avec bases séparées. Ces domaines ne constituent pas le book principal.</p><div class="related"><a href="modules/studies.html">Studies</a><a href="modules/fifo.html">FIFO</a><a href="modules/simulation.html">Simulation</a></div></section></div>'
    body+='<h2>Six notions à garder séparées</h2><div class="glossary">'
    for title,text in [('Installation','Un serveur et son répertoire de données ; les comptes ne sont pas fédérés automatiquement.'),('Organisation','Entity : Demo, BNP ou l’entité de recette d’isolation. Périmètre de rattachement de l’utilisateur.'),('Utilisateur / desk','Une identité de connexion ; le desk ajoute des droits métier, actuellement surtout pour RFQ.'),('Client commercial','Société couverte dans le CRM et ses contacts ; ce n’est pas un compte d’accès.'),('Contrepartie juridique','Entité qui fait face au trade / risque ; distincte du nom d’un fournisseur RFQ.'),('Product / Deal','Product décrit et suit le contrat ; Deal représente une position effectivement bookée.')]:
        body+=f'<div><strong>{E(title)}</strong><p>{E(text)}</p></div>'
    body+='</div><h2>Comment lire les statuts</h2><div class="badges">'+badge('Observé en base','proof')+badge('Implémenté dans le code')+badge('Recette datée','proof')+badge('À ajuster / compléter','pending')+'</div><p class="note">Les fonctionnalités listées sur les fiches sont implémentées selon le code et les documents lus. Les preuves indiquent ce qui a effectivement été exercé, quand et sur quelle base. Cet atlas ne prétend pas avoir retesté toute l’application.</p>'
    body+='<h2>Tous les modules</h2><div class="toolbar"><label for="moduleGroup">Domaine</label><select id="moduleGroup" data-group><option value="">Tous les domaines</option>'+''.join(f'<option>{E(g)}</option>' for g in GROUPS)+'</select><button data-print>Imprimer cette vue</button></div>'+modules_grid()
    page('overview','Vue globale',body)

def module_pages():
    for m in MODULES:
        body=f'<div class="eyebrow">Module · {E(m["group"])}</div><h1>{E(m["title"])}</h1><p class="lead">{E(m["goal"])}</p><div class="badges">{badge(m["state"])}{badge("Code inspecté le 13/10")}</div><p class="note"><strong>Acteurs et droits.</strong> {E(m["actors"])}</p><div class="facts">'
        for table in m['tables']:
            value=N(COUNTS[table]) if table in COUNTS else 'Absente'
            body+=f'<div class="fact"><b>{E(value)}</b>{E(TABLE_LABELS.get(table,table))}<br><code>{E(table)}</code></div>'
        body+='</div><div class="sectiongrid"><section class="panel"><h3>Entrées</h3>'+ul(m['inputs'])+'</section><section class="panel"><h3>Ce que le module produit</h3>'+ul(m['outputs'])+'</section></div><h2>Parcours écran et interactions</h2><p>'+E(' · '.join(m['screens']))+'</p><div class="flow">'
        for index,step in enumerate(m['flow']):
            body+=f'<div class="step"><span class="num">{index+1:02d}</span>{E(step)}</div>'
        body+='</div><h2>Ce qui est implémenté</h2>'+ul(m['works'])+f'<div class="notice"><strong>Preuve et limite de vérification.</strong> {E(m["evidence"])}</div><h2>À ajuster ou compléter</h2>'
        for priority,title,text in m['limits']:
            body+=f'<div class="issue"><div>{badge(priority,priority.lower())}</div><div><h3>{E(title)}</h3><p>{E(text)}</p></div></div>'
        body+='<h2>Modules liés</h2><div class="related">'+''.join(f'<a href="{related}.html">{E(BY_ID[related]["title"])}</a>' for related in m['related'])+'</div><details><summary>Sources de cette fiche</summary>'+ul(m['sources'])+'</details><p class="note">Les nombres représentent les lignes présentes dans la base principale, pas des volumes validés de production. « Absente » signifie table non présente dans cette base. Le code et les environnements de recette peuvent être plus récents.</p>'
        page(m['id'],m['title'],body,True)

PURPOSE={1:'Administration générale et propriétaire des 6 campagnes de simulation.',2:'Espace de travail principal : tous les Deals actuels, la plupart des Product et RFQ.',3:'Ops Maker UAT initial : saisie/contrôle opérationnel selon workflow.',4:'Checker UAT initial : validation opérationnelle selon workflow.',5:'Recette de séparation des accès dans une autre entité.',6:'Second Ops Maker créé pour la recette du 02/10.',7:'Second Checker créé pour la recette du 02/10.',8:'Recette indépendante d’accès aux Deals dans une autre entité.',9:'Administration BNP locale ; pas d’habilitation de desk RFQ actuellement.',10:'Répondant bancaire local : prépare, price, valide et publie.'}
RIGHTS={'read':'Lire','prepare':'Préparer','price':'Pricer','solicit':'Envoyer','select':'Sélectionner','book':'Booker','organize':'Partager / organiser','validate_quote':'Valider le prix','publish_quote':'Publier le prix'}

def accounts():
    entities={e['id']:e['name'] for e in DATA['entities']}
    desks={d['id']:d for d in DATA['desks']}
    members={m['user_id']:m for m in DATA['memberships'] if m['active']}
    body='<div class="eyebrow">Identités · environnements · données</div><h1>Quels comptes existent,<br>et à quoi servent-ils ?</h1><p class="lead">10 comptes actifs dans la base principale. Les comptes des simulations et des essais RFQ vivent dans d’autres bases : un même identifiant peut y être répété sans désigner le même compte.</p>'
    body+=metrics([('10','Comptes principaux, tous actifs'),('2','Administrateurs globaux'),('90','Comptes dans 30 bases de simulation'),('77','Comptes dans 23 bases de recette RFQ')])
    body+='<div class="notice critical"><strong>Deux systèmes de droits coexistent.</strong> Le rôle global détermine certains accès à l’administration et au Life Cycle. Les nouvelles RFQ vérifient des droits de desk séparés, sans exception admin. Inversement, admin reste global dans plusieurs anciennes API : le rôle de bnp.admin n’est pas encore un rôle d’administration entièrement limité à BNP.</div>'
    body+='<div class="tabs" data-tabs role="tablist" aria-label="Inventaire des comptes"><button class="btn" role="tab" aria-selected="true" aria-controls="mainAccounts">Base principale</button><button class="btn" role="tab" aria-selected="false" aria-controls="otherAccounts">Bases isolées</button><button class="btn" role="tab" aria-selected="false" aria-controls="accessMap">Qui peut faire quoi ?</button></div><section class="tabpane" id="mainAccounts"><h2>Les trois organisations</h2><div class="orgs">'
    for entity in DATA['entities']:
        users=[u for u in DATA['users'] if u['entity_id']==entity['id']]
        org_desks=[d['name'] for d in DATA['desks'] if d['entity_id']==entity['id']]
        body+=f'<div class="org"><h3>{E(entity["name"])}</h3><p class="muted">Entity #{entity["id"]} · {len(users)} comptes · desks : {E(", ".join(org_desks) or "aucun")}</p>'
        for user in users:body+=f'<div class="member"><strong>{E(user["username"])}</strong><small>{E(user["role"])} · compte #{user["id"]}</small></div>'
        body+='</div>'
    body+='</div><h2>Inventaire exact des utilisateurs</h2><div class="toolbar"><label for="accountFilter">Filtrer les comptes</label><input id="accountFilter" data-filter="#accountRows tr" data-counter="accountCount" placeholder="Identifiant, organisation, rôle…"><span id="accountCount" class="note" aria-live="polite">10 comptes affichés</span></div><div class="tablewrap wide"><table><thead><tr><th>ID / identifiant</th><th>Organisation / rôle</th><th>Desk RFQ et droits actuels</th><th>Usage / création</th></tr></thead><tbody id="accountRows">'
    for user in DATA['users']:
        member=members.get(user['id'])
        rights=' · '.join(RIGHTS[x] for x in json.loads(member['rights_json'])) if member else 'Aucune habilitation RFQ de desk'
        desk=desks[member['desk_id']]['name'] if member else '—'
        body+=f'<tr><td><strong>{E(user["username"])}</strong><br><span class="muted">#{user["id"]} · actif</span><br><small>{E(user["email"])}</small></td><td>{E(entities[user["entity_id"]])}<br>{badge(user["role"])}</td><td><strong>{E(desk)}</strong><br>{E(rights)}</td><td>{E(PURPOSE[user["id"]])}<br><span class="muted">Créé le {E(user["created_at"][:10])}</span></td></tr>'
    body+='</tbody></table></div><h2>Où sont les dossiers actuels ?</h2><div class="tablewrap"><table><thead><tr><th>Objet</th><th>admin</th><th>test</th><th>Lecture pratique</th></tr></thead><tbody>'
    for table,label,text in [('products','Product','72 dossiers appartiennent à test ; visibilité bibliothèque et persistance sont différentes.'),('deals','Deals','Toutes les positions de la base principale sont créées pour test.'),('rfq_requests','RFQ','Les anciennes RFQ gardent l’accès créateur ; une seule nouvelle RFQ est sous desk.'),('valuation_notes','Notes de valorisation','Les notes sont liées aux Deals et valorisations de test.'),('portfolios','Portefeuilles','L’accès suit encore les contrôles de propriétaire de ce domaine.')]:
        values={row['user_id']:row['count'] for row in DATA['per_user'].get(table,[])}
        body+=f'<tr><td>{label}</td><td class="numeric">{values.get(1,0)}</td><td class="numeric">{values.get(2,0)}</td><td>{E(text)}</td></tr>'
    body+='<tr><td>Campagnes de simulation (fichiers)</td><td class="numeric">6</td><td class="numeric">0</td><td>Les six campagnes appartiennent à admin. Elles se consultent avec ce compte ; le simulateur filtre sur le propriétaire, pas sur le rôle admin seul.</td></tr>'
    body+='</tbody></table></div><div class="notice warn"><strong>Pourquoi admin et test ne montrent pas la même chose ?</strong> La liste des nouvelles RFQ suit les desks et organisations ; les historiques et les simulations suivent le créateur/propriétaire. La liste des Deals donne encore une vue globale à admin. Une vue différente ne signifie pas forcément que les dossiers ont disparu.</div></section>'
    body+='<section class="tabpane" id="otherAccounts" hidden><h2>Les environnements qui se ressemblent sans partager leurs comptes</h2><p>167 lignes de comptes supplémentaires, dans 53 bases secondaires recensées. Ce ne sont pas 167 personnes. Les archives compressées ne sont pas ouvertes et les sessions/processus ne sont pas déduits de la simple présence d’un fichier.</p><div class="sectiongrid"><section class="panel"><h3>Simulation entre agents</h3><p>6 campagnes arrêtées, chacune avec 5 bases d’acteurs : Hector, BNP, CA, SG et client. Chaque base contient admin, test et agent_… : 30 bases × 3 comptes = 90 comptes.</p><p>Achille est le superviseur ; aucune base d’acteur Achille n’est constatée.</p></section><section class="panel"><h3>Recettes RFQ</h3><p>23 bases sous tmp : essais des lots 2–7 et cinq essais du lot 8. 77 comptes de fixtures/QA, dont certains comptes techniques __rfq_transport__ inactifs.</p><p>Ces données ne sont ni des comptes à utiliser dans la base principale ni une connexion à une vraie banque.</p></section></div><h2>Inventaire par base isolée</h2><div class="toolbar"><label for="secondaryFilter">Filtrer</label><input id="secondaryFilter" data-filter="#secondaryRows tr" data-counter="secondaryCount" placeholder="BNP, agent_hector, lot8…"><span id="secondaryCount" class="note" aria-live="polite">53 bases affichées</span></div><div class="tablewrap wide"><table><thead><tr><th>Répertoire</th><th>Type</th><th>Comptes présents</th><th>État des comptes</th></tr></thead><tbody id="secondaryRows">'
    for base in DATA['secondary_databases']:
        users=base.get('accounts',[])
        org_names={e['id']:e['name'] for e in base.get('entities',[])}
        names=' · '.join(u['username']+' ('+u['role']+' · '+org_names.get(u.get('entity_id'),'sans organisation')+')' for u in users)
        active=sum(bool(u.get('is_active',True)) for u in users)
        body+=f'<tr><td><code>{E(base["path"])}</code></td><td>{E("Simulation" if base.get("category")=="simulation" else "Recette RFQ")}</td><td>{E(names or "Non lu")}</td><td>{active} actif(s), {len(users)-active} inactif(s)</td></tr>'
    body+='</tbody></table></div></section><section class="tabpane" id="accessMap" hidden><h2>Les comptes à utiliser selon le parcours</h2><div class="tablewrap wide"><table><thead><tr><th>Compte</th><th>Possible actuellement</th><th>Ce qui bloque / à préparer</th></tr></thead><tbody><tr><td><strong>admin</strong></td><td>Administration globale, référentiels, vues globales selon module.</td><td>Aucun droit de desk Sales ; pas de création/lecture automatique des nouvelles RFQ organisationnelles.</td></tr><tr><td><strong>test</strong></td><td>Travail principal et historiques. Sales : lire, préparer, pricer, envoyer une nouvelle RFQ.</td><td>Pas de select, book ou organize sur les nouvelles RFQ. Délai du tour BNP existant dépassé.</td></tr><tr><td><strong>bnp.pricing</strong></td><td>Pricing : lire, préparer, pricer, valider et publier une RFQ reçue compatible et ouverte.</td><td>Aucun cas bancaire/prix publié dans la base. Politique de desk à configurer ; tour reçu expiré.</td></tr><tr><td><strong>bnp.admin</strong></td><td>Administration au rôle global ; administration de la relation BNP selon les gardes RFQ.</td><td>Pas de membership Pricing. Pour une politique liée à une RFQ reçue, il faut un administrateur habilité à la lire ; pas d’auto-attribution de droits.</td></tr><tr><td><strong>ops_maker / checker</strong></td><td>Étapes Life Cycle/contrôles prévus par leur rôle et leur organisation.</td><td>Pas de droit RFQ de desk implicite. Les comptes dupliqués de recette ne remplacent pas une politique d’accès choisie.</td></tr></tbody></table></div><h2>État précis de l’essai BNP local</h2><div class="notice"><strong>RFQ-20261012-003</strong> — copie #91, Product #76, organisation Demo, desk Sales, responsable test. Tour #1 remis au desk Pricing de l’organisation BNP le 12/10 ; read_at non renseigné, aucun cas bancaire ni publication. Délai : 12/10/2026 21:33 Europe/Berlin, désormais dépassé.</div><p>La relation DEMO-BNP-RFQ est reconnue, sur EMTN / Note / Autocall / CHF / 1 000 000. Le traitement y est interdit. L’accord de trading Test BNP est, lui, EUR et porte la documentation de test TOTO : ces deux configurations ne forment pas une chaîne prête au traitement.</p><div class="related"><a href="modules/rfq.html">Parcours demandeur</a><a href="modules/rfq-bank.html">Parcours bancaire</a><a href="modules/rfq-network.html">Relation et canal</a><a href="modules/trading.html">Accord de trading</a></div></section>'
    body+='<h2>Ce qu’on ne change pas dans cet état des lieux</h2><p class="note">Aucun compte désactivé, mot de passe lu, droit ajouté ou dossier supprimé. Le plan propose de classer les comptes de recette avant toute décision de nettoyage, en préservant leurs liens d’audit. Les mots de passe ne sont ni vérifiés ni repris dans cette présentation.</p>'
    page('accounts','Comptes et environnements',body)

def roadmap():
    body='<div class="eyebrow">Travaux proposés · sans action sur l’application</div><h1>Un ordre de reprise lisible.</h1><p class="lead">Commencer par rendre les comptes, droits et états de l’installation cohérents. Puis exercer un parcours local court avant une ouverture bancaire réelle. Les extensions métier viennent ensuite selon leur valeur.</p><div class="notice">P0 = préalable à une ouverture/usage institutionnel, P1 = consolidation du parcours, P2 = extension. Ce classement est une proposition de priorisation, pas une liste d’incidents tous reproduits.</div>'
    for priority,title,action,key,proof in PRIORITIES:
        body+=f'<div class="issue"><div>{badge(priority,priority.lower())}</div><div><h3>{E(title)}</h3><p>{E(action)}</p><p class="note">Fondement : {E(proof)} · <a href="modules/{key}.html">Fiche du module</a></p></div></div>'
    body+='<h2>Le prochain parcours concret à qualifier</h2><div class="flow">'+''.join(f'<div class="step"><span class="num">{i+1:02d}</span>{E(step)}</div>' for i,step in enumerate(['Charger la version backend et son schéma','Choisir les droits Sales / politique Pricing','Dupliquer la RFQ avec un délai futur','test envoie, bnp.pricing prend en charge','Calcul privé → validation → publication','Sélection → accord externe → booking unique']))+'</div><p class="note">Aucune migration des anciens Deals/RFQ de test n’est proposée. L’activation du schéma moderne et les nouveaux dossiers suffisent au périmètre RFQ choisi. Le compte bnp.admin doit être distingué d’un administrateur d’organisation strict avant de multiplier les organisations dans une base commune.</p><h2>Critères de sortie</h2>'+ul(['Un compte de travail identifiable et des rôles sans ambiguïté.','Chaque objet et chaque écran indique organisation, auteur, version et état.','Un prix bancaire local reçu et un booking unique sur un dossier de recette neuf.','Une recette bilatérale isolée avec BNP avant toute demande réelle.','Des preuves de pricing/lifecycle/risque distinguées des commentaires IA et du simple succès HTTP.'])
    page('roadmap','Plan d’action',body)

def sources():
    body='<div class="eyebrow">Méthode · limites de preuve</div><h1>Ce qui a été vérifié,<br>et ce qui ne l’a pas été.</h1><p class="lead">Cette présentation est un inventaire documentaire, une lecture du code et une interrogation de bases en lecture seule. Elle explique les capacités et les écarts sans les transformer en une recette générale de production.</p>'
    body+='<div class="sectiongrid"><section class="panel"><h3>Observé maintenant</h3>'+ul(['Base principale : backend/data/structura.db, mode SQLite ro et query_only.','Comptes, rôles, organisations, memberships, objets et volumes.','53 bases secondaires nommées structura.db sous agent_workshop et tmp.','Routes frontend, routeurs API et chemins de contrôle d’accès.','Présence du code sur codex/rfq-network-lot-0, HEAD e5b17c8 avec changements locaux.'])+'</section><section class="panel"><h3>Limites de l’inventaire</h3>'+ul(['Pas de tests relancés, de marché téléchargé ou de moteur repricé.','Pas de serveur principal démarré/rechargé ni d’écriture dans ses bases.','Présence d’une table ou d’un résultat ≠ validation de sa méthode ou de sa fraîcheur.','Les recettes datées sont celles des rapports cités ; elles ne couvrent pas tous les modules.','Archives compressées, variables d’environnement de déploiement et sessions actives non auditées.'])+'</section></div><h2>Base et version examinées</h2><p><code>'+E(DATA['database'])+'</code></p><p class="note">Horodatage du relevé : '+E(DATA['observed_at'])+'. Les jeux anciens de recette sont conservés. Les nombres sont des comptages de lignes, sans prétendre qu’ils correspondent à un book de production.</p><h2>Routes couvertes par la carte</h2><p>Les fiches couvrent l’accueil et ses domaines, les routes clients, Pricer/Product, RFQ demandeur/banque, Relations et exécutions, Booking/Life Cycle, Risk/CCR, documents, Studies/FIFO, simulation et administration. Les onglets techniques du Pricer sont décrits dans leur module commun.</p><h2>Documents de référence</h2><div class="tablewrap"><table><thead><tr><th>Module</th><th>Sources relues / utilisées</th></tr></thead><tbody>'
    for m in MODULES:body+=f'<tr><td><a href="modules/{m["id"]}.html">{E(m["title"])}</a></td><td>'+''.join('<div><code>'+E(src)+'</code></div>' for src in m['sources'])+'</td></tr>'
    body+='</tbody></table></div><h2>Fichiers du livrable</h2>'+ul(['index.html : vue globale et interactions.','accounts.html : comptes, organisations, bases isolées et droits actuels.','modules/*.html : une fiche complète pour chaque module.','roadmap.html : travaux proposés et ordre de reprise.','database_snapshot.json : relevé daté filtré, sans mots de passe ni clés.','build_presentation.py et module_content.py : source de la présentation portable.'])+'<p class="note">Certaines notes anciennes présentent encore le RFQ réseau comme un projet. La fiche RFQ se fonde sur les lots 0–8 et la branche courante. Le cadrage d’accès par organisation reste applicable aux autres modules tant que leurs contrôles n’ont pas été harmonisés.</p>'
    page('sources','Sources et méthode',body)

if __name__=='__main__':
    missing=sorted({src for m in MODULES for src in m['sources'] if not (ROOT/src).is_file()})
    if missing:
        raise SystemExit('Missing source references: '+', '.join(missing))
    overview(); accounts(); roadmap(); sources(); module_pages()
    print(f'Generated {len(MODULES)+4} offline HTML pages ({len(MODULES)} modules).')
